          body.hash = "";

          this.hashData(JSON.stringify(body)).then((hash) => {
            if (hash !== respHash) {
              this.passwordActivationService.interruptedTransaction();
              this.showAlert("Ha ocurrido un error inesperado");
              throw new Error("Data integrity check failed");
            }
          });
        }
      }),
      catchError((error) => {
        if (error instanceof HttpErrorResponse) {
          let body = error.error;
          const respHash = body.hash;
          body.hash = "";

          this.hashData(JSON.stringify(body)).then((hash) => {
            if (hash !== respHash) {
              this.passwordActivationService.interruptedTransaction();
              this.showAlert("Ha ocurrido un error inesperado");
              throw new Error("Data integrity check failed");
            }
          });
        }
        return throwError(() => error);
      }),
    );
  }

