import { TestBed } from '@angular/core/testing';
import { HttpClientTestingModule, HttpTestingController } from '@angular/common/http/testing';
import { HTTP_INTERCEPTORS, HttpClient, HttpRequest, HttpResponse, HttpErrorResponse } from '@angular/common/http';
import { of, throwError } from 'rxjs';
import { HashInterceptor } from './hash-interceptor.interceptor';
import { PasswordActivationService } from '../services/password-activation.service';

describe('HashInterceptor', () => {
  let httpMock: HttpTestingController;
  let httpClient: HttpClient;
  let passwordActivationService: PasswordActivationService;

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule],
      providers: [
        HashInterceptor,
        {
          provide: HTTP_INTERCEPTORS,
          useClass: HashInterceptor,
          multi: true,
        },
        {
          provide: PasswordActivationService,
          useValue: {
            interruptedTransaction: jest.fn(),
          },
        },
      ],
    });

    httpMock = TestBed.inject(HttpTestingController);
    httpClient = TestBed.inject(HttpClient);
    passwordActivationService = TestBed.inject(PasswordActivationService);
  });

  afterEach(() => {
    httpMock.verify();
  });

  it('should pass through the request and validate the response hash', (done) => {
    const mockResponse = { data: 'test', hash: 'validHash' };
    const hashInterceptor = TestBed.inject(HashInterceptor);
    jest.spyOn(hashInterceptor, 'hashData').mockResolvedValue('validHash');

    httpClient.get('/test').subscribe((response) => {
      expect(response).toEqual(mockResponse);
      done();
    });

    const req = httpMock.expectOne('/test');
    req.flush(mockResponse);
  });

  it('should handle hash mismatch in response', (done) => {
    const mockResponse = { data: 'test', hash: 'invalidHash' };
    const hashInterceptor = TestBed.inject(HashInterceptor);
    jest.spyOn(hashInterceptor, 'hashData').mockResolvedValue('validHash');

    httpClient.get('/test').subscribe({
      next: () => fail('should have failed with hash mismatch'),
      error: (error) => {
        expect(passwordActivationService.interruptedTransaction).toHaveBeenCalled();
        expect(error.message).toBe('Data integrity check failed');
        done();
      },
    });

    const req = httpMock.expectOne('/test');
    req.flush(mockResponse);
  });

  it('should handle hash mismatch in error response', (done) => {
    const mockErrorResponse = { data: 'test', hash: 'invalidHash' };
    const hashInterceptor = TestBed.inject(HashInterceptor);
    jest.spyOn(hashInterceptor, 'hashData').mockResolvedValue('validHash');

    httpClient.get('/test').subscribe({
      next: () => fail('should have failed with hash mismatch'),
      error: (error) => {
        expect(passwordActivationService.interruptedTransaction).toHaveBeenCalled();
        expect(error.message).toBe('Data integrity check failed');
        done();
      },
    });

    const req = httpMock.expectOne('/test');
    req.flush(mockErrorResponse, { status: 500, statusText: 'Server Error' });
  });
});
