Aquí tienes el código de la prueba unitaria para el método `arrayBufferToHex`:

```ts
import { TestBed } from "@angular/core/testing";
import { HashInterceptor } from "../../../../core/utils/interceptors/hash-interceptor.interceptor";

describe("HashInterceptor", () => {
  let hashInterceptor: HashInterceptor;

  beforeEach(() => {
    TestBed.configureTestingModule({
      providers: [HashInterceptor],
    });

    hashInterceptor = TestBed.inject(HashInterceptor);
  });

  it("should convert ArrayBuffer to hexadecimal string", () => {
    const buffer = new Uint8Array([1, 2, 3, 4]).buffer;
    const expectedHex = "01020304";

    const hexString = hashInterceptor.arrayBufferToHex(buffer);

    expect(hexString).toBe(expectedHex);
  });

  it("should convert an empty ArrayBuffer to an empty string", () => {
    const buffer = new Uint8Array([]).buffer;
    const expectedHex = "";

    const hexString = hashInterceptor.arrayBufferToHex(buffer);

    expect(hexString).toBe(expectedHex);
  });

  it("should convert ArrayBuffer with single byte to hexadecimal string", () => {
    const buffer = new Uint8Array([255]).buffer;
    const expectedHex = "ff";

    const hexString = hashInterceptor.arrayBufferToHex(buffer);

    expect(hexString).toBe(expectedHex);
  });

  it("should convert ArrayBuffer with multiple bytes to hexadecimal string", () => {
    const buffer = new Uint8Array([16, 32, 48, 64, 128, 255]).buffer;
    const expectedHex = "1020304080ff";

    const hexString = hashInterceptor.arrayBufferToHex(buffer);

    expect(hexString).toBe(expectedHex);
  });
